#!/usr/bin/env node

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// 项目根目录
const PROJECT_ROOT = path.resolve(__dirname, '../../src');
const DATA_DIR = path.resolve(__dirname, '../data');

// 组件分类映射
const CATEGORIES = {
  'Animations': [
    'AnimatedContent', 'BlobCursor', 'ClickSpark', 'Crosshair', 'Cubes',
    'FadeContent', 'GlareHover', 'ImageTrail', 'Magnet', 'MagnetLines',
    'MetaBalls', 'MetallicPaint', 'Noise', 'PixelTrail', 'PixelTransition',
    'Ribbons', 'SplashCursor', 'StarBorder'
  ],
  'Backgrounds': [
    'Aurora', 'Balatro', 'Ballpit', 'Beams', 'Dither', 'DotGrid',
    'GridDistortion', 'GridMotion', 'Hyperspeed', 'Iridescence',
    'LetterGlitch', 'Lightning', 'LiquidChrome', 'Orb', 'Particles',
    'RippleGrid', 'ShapeBlur', 'Silk', 'Squares', 'Threads', 'Waves'
  ],
  'Components': [
    'AnimatedList', 'BounceCards', 'CardSwap', 'Carousel', 'ChromaGrid',
    'CircularGallery', 'Counter', 'DecayCard', 'Dock', 'ElasticSlider',
    'FlowingMenu', 'FluidGlass', 'FlyingPosters', 'Folder', 'GlassIcons',
    'GooeyNav', 'InfiniteMenu', 'InfiniteScroll', 'Lanyard', 'MagicBento',
    'Masonry', 'ModelViewer', 'PixelCard', 'ProfileCard', 'RollingGallery',
    'SpotlightCard', 'Stack', 'Stepper', 'TiltedCard'
  ],
  'TextAnimations': [
    'ASCIIText', 'BlurText', 'CircularText', 'CountUp', 'CurvedLoop',
    'DecryptedText', 'FallingText', 'FuzzyText', 'GlitchText', 'GradientText',
    'RotatingText', 'ScrambledText', 'ScrollFloat', 'ScrollReveal',
    'ScrollVelocity', 'ShinyText', 'SplitText', 'TextCursor', 'TextPressure',
    'TextTrail', 'TrueFocus', 'VariableProximity'
  ]
};

// 技术栈映射
const TECH_STACKS = {
  'content': { name: 'js-css', extension: '.jsx', hasCSS: true },
  'tailwind': { name: 'js-tailwind', extension: '.jsx', hasCSS: false },
  'ts-default': { name: 'ts-css', extension: '.tsx', hasCSS: true },
  'ts-tailwind': { name: 'ts-tailwind', extension: '.tsx', hasCSS: false }
};

// 读取文件内容
function readFileIfExists(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      return fs.readFileSync(filePath, 'utf8');
    }
  } catch (error) {
    console.warn(`无法读取文件: ${filePath}`, error.message);
  }
  return null;
}

// 生成组件数据
function generateComponentData(category, componentName, techStack, techConfig) {
  const basePath = path.join(PROJECT_ROOT, techStack, category, componentName);
  const componentFile = `${componentName}${techConfig.extension}`;
  const cssFile = `${componentName}.css`;
  
  const componentPath = path.join(basePath, componentFile);
  const cssPath = path.join(basePath, cssFile);
  
  // 读取组件源码
  const componentCode = readFileIfExists(componentPath);
  const cssCode = techConfig.hasCSS ? readFileIfExists(cssPath) : null;
  
  // 读取演示代码
  const demoPath = path.join(PROJECT_ROOT, 'demo', category, `${componentName}Demo.jsx`);
  const demoCode = readFileIfExists(demoPath);
  
  // 读取代码常量
  const codeConstantPath = path.join(PROJECT_ROOT, 'constants', 'code', category, `${componentName.toLowerCase()}Code.js`);
  const codeConstant = readFileIfExists(codeConstantPath);
  
  return {
    name: componentName,
    category: category.toLowerCase(),
    techStack: techConfig.name,
    files: {
      component: {
        filename: componentFile,
        content: componentCode,
        path: componentPath
      },
      css: techConfig.hasCSS ? {
        filename: cssFile,
        content: cssCode,
        path: cssPath
      } : null,
      demo: {
        filename: `${componentName}Demo.jsx`,
        content: demoCode,
        path: demoPath
      },
      codeConstant: {
        filename: `${componentName.toLowerCase()}Code.js`,
        content: codeConstant,
        path: codeConstantPath
      }
    },
    metadata: {
      hasCSS: techConfig.hasCSS,
      extension: techConfig.extension,
      isTypeScript: techConfig.extension === '.tsx',
      isTailwind: techConfig.name.includes('tailwind'),
      generatedAt: new Date().toISOString()
    }
  };
}

// 生成所有组件数据
function generateAllComponentsData() {
  const allComponents = {};
  
  console.log('🚀 开始生成组件数据...\n');
  
  // 遍历所有分类
  Object.entries(CATEGORIES).forEach(([category, components]) => {
    console.log(`📁 处理分类: ${category} (${components.length} 个组件)`);
    allComponents[category.toLowerCase()] = {};
    
    // 遍历分类下的所有组件
    components.forEach(componentName => {
      console.log(`  🧩 处理组件: ${componentName}`);
      allComponents[category.toLowerCase()][componentName.toLowerCase()] = {};
      
      // 遍历所有技术栈
      Object.entries(TECH_STACKS).forEach(([techStack, techConfig]) => {
        const componentData = generateComponentData(category, componentName, techStack, techConfig);
        allComponents[category.toLowerCase()][componentName.toLowerCase()][techConfig.name] = componentData;
      });
    });
  });
  
  return allComponents;
}

// 生成索引数据
function generateIndexData(allComponents) {
  const index = {
    metadata: {
      generatedAt: new Date().toISOString(),
      totalCategories: Object.keys(CATEGORIES).length,
      totalComponents: Object.values(CATEGORIES).reduce((sum, components) => sum + components.length, 0),
      totalTechStacks: Object.keys(TECH_STACKS).length,
      version: '1.0.0'
    },
    categories: {},
    components: [],
    techStacks: Object.values(TECH_STACKS).map(config => config.name)
  };
  
  // 生成分类索引
  Object.entries(CATEGORIES).forEach(([category, components]) => {
    index.categories[category.toLowerCase()] = {
      name: category,
      count: components.length,
      components: components.map(name => name.toLowerCase())
    };
  });
  
  // 生成组件列表
  Object.entries(allComponents).forEach(([category, categoryComponents]) => {
    Object.entries(categoryComponents).forEach(([componentName, techStackVariants]) => {
      index.components.push({
        name: componentName,
        displayName: Object.values(techStackVariants)[0].name,
        category: category,
        techStacks: Object.keys(techStackVariants),
        hasCSS: Object.values(techStackVariants).some(variant => variant.metadata.hasCSS),
        isNew: ['fluid-glass', 'cubes', 'masonry', 'text-trail', 'curved-loop', 'magic-bento', 'ripple-grid'].includes(componentName),
        isUpdated: ['split-text', 'star-border'].includes(componentName)
      });
    });
  });
  
  return index;
}

// 主函数
async function main() {
  try {
    console.log('🎨 React Bits MCP 组件数据生成器\n');
    console.log('=' .repeat(50));
    
    // 确保数据目录存在
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
      console.log(`📁 创建数据目录: ${DATA_DIR}`);
    }
    
    // 生成所有组件数据
    const allComponents = generateAllComponentsData();
    
    // 生成索引数据
    const indexData = generateIndexData(allComponents);
    
    // 写入文件
    console.log('\n💾 保存数据文件...');
    
    // 保存完整组件数据
    const componentsDataPath = path.join(DATA_DIR, 'components.json');
    fs.writeFileSync(componentsDataPath, JSON.stringify(allComponents, null, 2));
    console.log(`✅ 组件数据已保存: ${componentsDataPath}`);
    
    // 保存索引数据
    const indexDataPath = path.join(DATA_DIR, 'index.json');
    fs.writeFileSync(indexDataPath, JSON.stringify(indexData, null, 2));
    console.log(`✅ 索引数据已保存: ${indexDataPath}`);
    
    // 按分类保存数据
    Object.entries(allComponents).forEach(([category, categoryData]) => {
      const categoryDataPath = path.join(DATA_DIR, `${category}.json`);
      fs.writeFileSync(categoryDataPath, JSON.stringify(categoryData, null, 2));
      console.log(`✅ ${category} 分类数据已保存: ${categoryDataPath}`);
    });
    
    // 生成统计信息


    console.log('\n📊 生成统计信息:');
    console.log(`  📁 分类数量: ${indexData.metadata.totalCategories}`);
    console.log(`  🧩 组件总数: ${indexData.metadata.totalComponents}`);
    console.log(`  🛠️ 技术栈数量: ${indexData.metadata.totalTechStacks}`);
    console.log(`  📄 总文件数: ${indexData.metadata.totalComponents * indexData.metadata.totalTechStacks}`);
    
    console.log('\n🎉 数据生成完成！');
    console.log('=' .repeat(50));
    
  } catch (error) {
    console.error('❌ 生成数据时出错:', error);
    process.exit(1);
  }
}

// 运行主函数
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

export { generateAllComponentsData, generateIndexData };